     "formula": "「長期來說」放在句首或句中，強調從長時間的角度來看某事，用來引導或強調一個在短期內可能不明顯，但在長期內會逐漸顯現的情況或影響，通常用於討論長期的趨勢、效果、計畫或未來的情況。 表示說話者認為前面所提到的事情並不重要或沒有特殊意義，有「不認同對方，否定先前或一般習慣的想法」的意味。這種反問的方式也有要對方或讀者再次思考某些事情或觀念的意味。 spring bamboo rapidly grows after rain, as many new things emerge in rapid succession to display one’s skill to the full; to bring one’s talents into full play to rapidly go up in the world; to have a meteoric rise to stop before going too far ;to know where to stop; to not overdo it 「一度」常用於書面語，有兩個意思，一是「一次」的意思，如：「一年一度的中秋節又到了。」另一個意思則是表示「過去某一段時間發生過」，沒有明確的時間點與時間長短，只知道曾經發生過，且持續一段時間，現在沒有發生。本課採用第二種意思。",
