     "formula": "本課的「Vs 於」有比較的意味，因此「於」之後所接的是所比較的對象或基準。「A Vs於 B」的意思是「A比B Vs」，Vs多為單音節詞。 to adapt, to be flexible, to handle the unexpected don’t mind taking the trouble to do something﹔ always willing to undertake troublesome task having photographic memory, never forget after seeing 「且不論/且不說」常放在句首，表示暫時不考慮或排除「且不論/且不說」後面所接的對象或因素，而是把重點放在後句要討論或觀察事情的重點上，引出更重要或更有說服力的內容，強調後者的重要性。多見於書面語或稍正式的語境。 「就是⋯⋯也⋯⋯」（見第三冊）是假設的語氣，若「就是」後面的情況或條件發生了，「也」之後的結果仍然不變的意思。在本課「別說 A，就是 B 也/都⋯⋯」的句型中，強調無論一般情況（A），或是較誇張的情況（B）都不會改變，用在前後情況對比上。",
