     "formula": "「何況」用在後句，以反問語氣表示前文的說明或道理是很清楚可知的，不用多說，另外也可能作補充用，表示在已有的理由外補充說明，或意思上更深一層。在「何況」之前也常接「更、又」。此外也有「連⋯⋯(更)何況⋯⋯」的用法，強調「連」所接的情況都做不到了，更不用說「(更)何況」後面的情形了。 「何苦」是「為什麼要這麼辛苦/麻煩/煩惱」的意思，句末常帶有「呢？」，用反問加強語氣，表示說話者認為這麼做不值得、不需要的意思，帶有規勸的語氣，但有時也稍帶責備的語氣。",
