     "formula": "「即便」表示即使某種情況發生，通常是不利的情況，結果仍不改變，與「即使」都是表示讓步語氣的連詞，但在語氣強弱與使用上有一些差異。「即便」語氣較弱，也偏書面語，不能單獨使用。而「也、都、還」之後表達的是另一個更值得重視的部分，所以後半短句往往是句子的重點所在。",
