     "label": null,
     "formula": "「何謂」有「什麼是」、「如何定義⋯⋯」，以及「⋯⋯的意義是什麼」的意思。常用於書面語或正式語境中，也常見於演講、文章或討論中，表達對某一概念或事物的提問、解釋或說明其意義或觀點，用以引出需要定義或討論的主題。「何謂」既能表達提問，也可用於自問自答的說明。 to have no way out, be utterly helpless, have no alternative harbor evil intentions, ill-intentioned offend against Heaven and reason-atrocious, outrageous always on the lookout for petty advantages 意思是在某個條件發生後「馬上可以」或是「達到標準」的意思，屬於正式的用法，也常見於食品包裝上或公文上。另外得注意「即可」是較文言的說法，因此句子須搭配正式的詞。 「上」的意思隨著上下文句有所不同，可能是指 1.天上；2.較高的地位、等級或階級架構；或是 3.順序較前的方向。而「下」相對於「上」則可能是 1.人間；2.地位、等級較低的人物或階級架構較低；或是 3.順序較後的方向。另外，也可能是指地理環境、位置上相對的兩端。",
