     "label": null,
     "formula": "「備」在此處是「全都、完全」的意思，表示完全地受到特別的對待。在「備受」之後多是雙音節動詞或有雙音節動詞的短語。 「與其說......，不如說......」與「與其......不如......」結構看似相同，然而「與其說......，不如說......」偏向觀點和立場的修正或解釋，用來表示對原本A的意見，提出B看法、觀點，有理性分析的語氣。像是:畢業後的學習與其說是職場壓力而不得不學，不如說是對自我成長的要求。而「與其......不如......」則為A與B實際行為或情況的選擇",
