     "formula": "「不為過」的意思是「不算過分、不算錯誤」，口語的說法是「沒有什麼不對」，在使用這樣的句型時隱含了一個假設：在一般情況下，這樣的形容有點誇張的感覺，但因為在「即使」前面給了證據或說明，因此就顯得不過分、不誇張。表示發生「即使」後面的情況也不算過分或不算錯誤，有說話者認同的意思。 「反而」的意思，「反倒」語氣更強烈，更偏向主觀及強調結果的出乎意料，具有轉折或對比的作用。表示事情走向或結果與前句描述的、先前想像的不同，甚至相反，有時是前後句對比，指出不合理之處。使用時，常伴隨著驚訝、無法理解或強調的語氣。",
